const express = require('express');
const { FileStore } = require('@tus/file-store');
const fs = require('fs');
const path = require('path');
const { authenticateCustomer } = require('../auth');

const router = express.Router();
const datastore = new FileStore({ directory: './tus_storage' });

router.get('/api/tus/preview/:uploadId', authenticateCustomer, async (req, res) => {
  const upload = await datastore.getUpload(req.params.uploadId);
  if (!upload) return res.status(404).json({ error: 'File chunk not found' });

  if (upload.metadata?.customerId !== req.customer.id) {
    return res.status(403).json({ error: 'Forbidden: you cannot preview another customer upload' });
  }

  const filePath = path.join('./tus_storage', req.params.uploadId);
  res.setHeader('Content-Type', upload.metadata?.filetype || 'application/octet-stream');
  fs.createReadStream(filePath, { end: 2048 }).pipe(res);
});
